import math
from numbers import Real


def _finite_tuple(value, length, name):
    if not isinstance(value, tuple) or len(value) != length:
        raise TypeError(name + " has the wrong shape")
    for item in value:
        if isinstance(item, bool) or not isinstance(item, Real):
            raise TypeError(name + " must contain real numbers")
        if not math.isfinite(item):
            raise ValueError(name + " must contain finite numbers")


def project_to_box_edge(origin, direction, box):
    _finite_tuple(origin, 2, "origin")
    _finite_tuple(direction, 2, "direction")
    _finite_tuple(box, 4, "box")
    x, y = origin
    dx, dy = direction
    xmin, ymin, xmax, ymax = box
    if not xmin < xmax or not ymin < ymax:
        raise ValueError("invalid box")
    if not (xmin < x < xmax and ymin < y < ymax):
        raise ValueError("origin must be strictly inside the box")
    if dx == 0 and dy == 0:
        raise ValueError("direction must be nonzero")

    tx = math.inf if dx == 0 else ((xmax - x) / dx if dx > 0 else (xmin - x) / dx)
    ty = math.inf if dy == 0 else ((ymax - y) / dy if dy > 0 else (ymin - y) / dy)
    t = max(tx, ty)
    return float(x + t * dx), float(y + t * dy), float(t)

